<?php

include_once __DIR__ . '/dns__lib.php';
include_once dirname(__DIR__, 2) . '/lib/php/kloxo_knot.php';

/**
 * Knot DNS driver. Zones are master files under /var/lib/knot/zones and the
 * zone list is /etc/knot/knot.conf, both generated by KloxoKnot (validated with
 * kzonecheck / knotc conf-check, installed atomically, reloaded).
 */
class dns__knot extends dns__
{
	/** Test hook: base / bindirs for KloxoKnot (empty on a real server). */
	public static array $opt = array();

	function __construct()
	{
		parent::__construct();
	}

	static function unInstallMe()
	{
		parent::unInstallMeTrue('knot');
	}

	static function installMe()
	{
		if (KloxoKnot::bin('knotc') === '' || KloxoKnot::bin('kzonecheck') === '') {
			include_once dirname(__DIR__, 2) . '/lib/php/kloxo_apt.php';
			KloxoApt::install(KloxoKnot::PACKAGES);
		}
		// Give the daemon a valid knot.conf (listen addresses, current zones) before
		// Switch Program enables the unit.
		try {
			self::applyKnotConf();
		} catch (Throwable $e) {
			log_log('dns_knot', 'install: ' . $e->getMessage());
		}

		parent::installMeTrue('knot');
	}

	/** @return array<string,mixed> */
	private static function knotLists(string $server = 'localhost'): array
	{
		$m = rl_exec_get('localhost', 'localhost', 'getDnsMasters', array($server));
		$s = rl_exec_get('localhost', 'localhost', 'getDnsSlaves', array($server));
		$ips = rl_exec_get('localhost', 'localhost', 'getIpfromARecord', array($server, true));

		return array(
			'listen' => KloxoKnot::serverAddresses(),
			'masters' => is_array($m) ? array_values($m) : array(),
			'slaves' => is_array($s) ? array_values($s) : array(),
			'transfer' => is_array($ips) ? array_values($ips) : array(),
		);
	}

	private static function applyKnotConf(string $server = 'localhost'): void
	{
		KloxoKnot::applyConf(self::knotLists($server), self::$opt);
	}

	/** Records of the dns object as plain arrays (the objects carry far more than renderZone reads). */
	private function recordList(): array
	{
		$out = array();
		foreach ((array) $this->main->dns_record_a as $o) {
			if (!is_object($o)) {
				continue;
			}
			$row = array();
			foreach (array('ttype', 'hostname', 'param', 'priority', 'port', 'weight', 'flag', 'tag') as $k) {
				$row[$k] = isset($o->$k) ? $o->$k : null;
			}
			$out[] = $row;
		}

		return $out;
	}

	function createConfFile()
	{
		$domains = array($this->main->nname);

		foreach ((array) $this->main->__var_addonlist as $d) {
			$domains[] = $d->nname;
		}

		foreach ($domains as $d) {
			$zone = array(
				'domain' => (string) $d,
				'ttl' => $this->main->ttl,
				'soa_ns' => $this->main->soanameserver,
				'hostmaster' => ($this->main->hostmaster) ? $this->main->hostmaster : "admin@{$this->main->nname}",
				'serial' => $this->main->__var_ddate,
				'records' => $this->recordList(),
			);

			try {
				$r = KloxoKnot::installZone($zone, self::$opt);
			} catch (KloxoKnotException $e) {
				throw new lxException('Knot DNS: ' . $e->getMessage(), '', (string) $d);
			}

			foreach ($r['warnings'] as $w) {
				log_log('dns_knot', "{$d}: {$w}");
			}
		}
	}

	function syncCreateConf()
	{
		try {
			self::applyKnotConf((string) $this->main->syncserver);
		} catch (KloxoKnotException $e) {
			throw new lxException('Knot DNS: ' . $e->getMessage(), '', (string) $this->main->nname);
		}
	}

	// The transfer list is part of knot.conf; refresh it the same way.
	function createAllowTransferIps()
	{
		$this->syncCreateConf();
	}
}
